mapper.select:
SELECT CAST(l.id AS CHAR) AS id, l.title, l.rent_cent AS rentCent, l.publish_status AS publishStatus, l.is_special AS special, u.occupancy_status AS occupancyStatus
FROM house_listing l JOIN property_unit u ON u.id = l.unit_id
WHERE l.landlord_id = #{landlordId}
ORDER BY l.updated_at DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE house_listing l JOIN property_unit u ON u.id = l.unit_id
SET l.publish_status = 'PUBLISHED', l.published_at = #{now}, l.updated_at = #{now}
WHERE l.id = #{id} AND l.landlord_id = #{landlordId} AND u.occupancy_status = 'VACANT'

UPDATE house_listing
SET publish_status = 'OFFLINE', offline_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND landlord_id = #{landlordId}

UPDATE house_listing
SET is_special = #{enabled}, special_sort = #{sort}, updated_at = #{now}
WHERE id = #{id} AND landlord_id = #{landlordId}
